const getBase64 = (str: string) => str.includes(',') ? str.split(',')[1] : str;

export const analyzeKTP = async (base64Image: string): Promise<KTPData | null> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';
  try {
    const response = await ai.models.generateContent({
      model,
      contents: { 
        parts: [
          { text: "Extract Name, NIK, and Address from this Indonesian KTP. Return JSON: {name, nik, address}" }, 
          { inlineData: { mimeType: 'image/jpeg', data: getBase64(base64Image) } }
        ] 
      },
      config: { responseMimeType: "application/json" }
    });
    return JSON.parse(response.text);
  } catch { return null; }
};

export const analyzeSTNK = async (base64Image: string): Promise<STNKData | null> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
