};

export const analyzeVehicleVerification = async (images: { label: string, base64: string }[]): Promise<{ success: boolean; data?: VehicleVerificationData; error?: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';
  const prompt = `You are a Surepath AI Insurance Inspector. Review these 5 vehicle photos (Front, Back, Left, Right, Interior). 
  Scoring Matrix (0-100):
  - Clarity & Lighting (20%)
  - Evidence of physical damage/dents/scratches (40%)
  - Image manipulation/AI editing detection (20%)
  - Consistency across photos (20%)
  Minimum score to pass is 80.
  Output JSON: { "overallScore": number, "detectedIssues": string[], "insights": "Indonesian explanation", "matchWithSTNK": boolean }`;

  try {
    const parts = images.map(img => ({
      inlineData: { mimeType: 'image/jpeg', data: getBase64(img.base64) }
    }));
    const response = await ai.models.generateContent({
      model,
      contents: { parts: [{ text: prompt }, ...parts] },
      config: { responseMimeType: "application/json" }
    });
    return { success: true, data: JSON.parse(response.text) };
  } catch (error) {
    return { success: false, error: "Verification failed." };
  }
};

export const analyzeClaimPhoto = async (base64Image: string): Promise<{ success: boolean; data?: ClaimAnalysisData; error?: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';
  const prompt = `Analisa foto kerusakan kendaraan ini. Berikan hasil dalam JSON: { "severity": "Ringan" | "Sedang" | "Berat" | "Total Loss", "totalEstimasi": number, "rincianPart": [{ "namaPart": "string", "kondisi": "string", "tindakan": "Perbaiki" | "Ganti", "estimasiBiaya": number }], "aiInsight": "string", "rekomendasiBengkel": "string" }`;
  try {
    const response = await ai.models.generateContent({
      model,
      contents: { 
        parts: [
          { text: prompt }, 
          { inlineData: { mimeType: 'image/jpeg', data: getBase64(base64Image) } }
        ] 
      },
      config: { responseMimeType: "application/json" }
    });
    return { success: true, data: JSON.parse(response.text) };
  } catch (error) {
    return { success: false, error: "Gagal menganalisa klaim." };
  }
};

