          <div className="absolute top-0 right-0 w-24 h-24 bg-primary-500/10 rounded-full -mr-10 -mt-10"></div>
          <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-[0.2em] mb-4">Total Amount Due</p>
          <h3 className="text-4xl font-black text-primary-500 tracking-tighter">{formatIDR(getCalculatedPremium() + STAMP_DUTY + (vehicle.selectedProvider?.adminFee || 0))}</h3>
       </div>

       <div className="space-y-3">
          {[
            { id: 'va', label: 'Virtual Account', icon: Landmark },
            { id: 'cc', label: 'Credit Card', icon: CreditCard },
            { id: 'ewallet', label: 'E-Wallet (OVO/GOPAY)', icon: Smartphone }
          ].map(m => (
            <button key={m.id} onClick={() => setStep(CarWizardStep.SUCCESS)} className="w-full p-6 glass-card rounded-3xl border border-black/5 flex items-center justify-between hover:border-primary-500 transition-all group">
               <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500"><m.icon size={24}/></div>
                  <span className="text-sm font-black uppercase tracking-tight dark:text-white">{m.label}</span>
               </div>
               <ChevronRight className="text-gray-300 group-hover:text-primary-500"/>
            </button>
          ))}
       </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#030303]">
      <header className="h-20 glass-card px-6 flex items-center justify-between border-b border-black/5">
        <button onClick={onBack} className="p-2 dark:text-gray-400"><ChevronLeft/></button>
        <div className="flex items-center gap-2">
          <ShieldPlus className="text-primary-500" size={24}/>
          <span className="font-black uppercase tracking-tighter text-gray-900 dark:text-white">Smart<span className="text-primary-500">Auto</span></span>
        </div>
        <div className="w-10"></div>
      </header>

      <main className="max-w-lg mx-auto p-6">
        {step === CarWizardStep.VEHICLE_DATA && renderStep1()}
        {step === CarWizardStep.COVERAGE && renderStep2()}
        {step === CarWizardStep.INSURANCE_SELECT && renderStep3()}
        {step === CarWizardStep.SUMMARY && renderSummary()}
        {step === CarWizardStep.KYC_UPLOAD && renderKYC()}
        {step === CarWizardStep.VEHICLE_UPLOAD && renderVehicleUpload()}
        {step === CarWizardStep.FINAL_CONFIRM && renderFinalConfirm()}
        {step === CarWizardStep.PAYMENT && renderPayment()}

        {step === CarWizardStep.SUCCESS && (
          <div className="py-20 text-center animate-pop-in space-y-6">
            <div className="w-24 h-24 bg-primary-500 text-white rounded-full flex items-center justify-center mx-auto shadow-2xl shadow-primary-500/40">
              <Check size={48} strokeWidth={4}/>
            </div>
            <h2 className="text-3xl font-black uppercase dark:text-white tracking-tighter">Proteksi Aktif!</h2>
            <p className="text-xs text-gray-500 font-bold uppercase tracking-widest leading-relaxed px-10">Neural Hub telah mensinkronisasi data unit Anda. Softcopy polis akan segera dikirimkan.</p>
