      d="M55 25C55 25 65 15 70 25C75 35 65 40 55 25Z" 
      fill="#ecfccb"
    />
  </svg>
);

// --- CORE WIZARD COMPONENT ---

const CarWizard = ({ onBack }: { onBack: () => void }) => {
  const [step, setStep] = useState<CarWizardStep>(CarWizardStep.VEHICLE_DATA);
  const [loading, setLoading] = useState(false);
  const [vehicle, setVehicle] = useState<VehicleState>({
    brand: '',
    model: '',
    year: 2025,
    price: 0,
    basePriceFromList: 0,
    plate: '',
    plateZone: '3',
    usage: 'PERSONAL',
    condition: 'NEW',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: {
      flood: false, earthquake: false, srcc: false, terrorism: false,
      authorizedWorkshop: false, tpl: 0, paDriver: 0, paPassenger: 0, passengers: 4
    },
    selectedProvider: null
  });

  const [user, setUser] = useState<UserState>({
    name: '', ktpNumber: '', address: '', email: '', phone: '',
    policyDelivery: 'WHATSAPP'
  });

  const [photos, setPhotos] = useState<Record<string, string>>({});
  const [aiResult, setAiResult] = useState<VehicleVerificationData | null>(null);

  // Price calculation
  const getCalculatedPremium = (provider?: Provider) => {
    if (!vehicle.price) return 0;
    const rate = getOJKRate(vehicle.price / 1000000, vehicle.plateZone, vehicle.insuranceType);
    let premium = (rate / 100) * vehicle.price;

    if (vehicle.expansions.authorizedWorkshop) premium += (AUTHORIZED_WORKSHOP_RATE / 100) * vehicle.price;
    if (vehicle.expansions.flood) premium += (EXPANSION_RATES.FLOOD / 100) * vehicle.price;
    if (vehicle.expansions.earthquake) premium += (EXPANSION_RATES.EARTHQUAKE / 100) * vehicle.price;
    if (vehicle.expansions.srcc) premium += (EXPANSION_RATES.SRCC / 100) * vehicle.price;
    if (vehicle.expansions.terrorism) premium += (EXPANSION_RATES.TERRORISM / 100) * vehicle.price;

    // Simple nominal for TPL
    premium += (vehicle.expansions.tpl / 1000) * 1; 

    return premium;
  };

  const handlePhotoUpload = async (id: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setPhotos(prev => ({ ...prev, [id]: base64 }));

      if (id === 'ktp') {
        setLoading(true);
        const data = await analyzeKTP(base64);
        if (data) setUser(prev => ({ ...prev, name: data.name, ktpNumber: data.nik, address: data.address }));
        setLoading(false);
      } else if (id === 'stnk') {
        setLoading(true);
        const data = await analyzeSTNK(base64);
        if (data) setVehicle(prev => ({ ...prev, plate: data.plate, vin: data.vin, engineNo: data.engineNo }));
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const verifyVehicle = async () => {
    setLoading(true);
    const surveyImages = [
      { label: 'front', base64: photos.carFront },
      { label: 'back', base64: photos.carBack },
      { label: 'left', base64: photos.carLeft },
      { label: 'right', base64: photos.carRight },
      { label: 'interior', base64: photos.interior },
    ].filter(i => i.base64);

    const res = await analyzeVehicleVerification(surveyImages as any);
    setLoading(false);
    if (res.success && res.data) {
      setAiResult(res.data);
    }
  };

  // UI Renders
  const renderStep1 = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="space-y-4">
        <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-widest ml-1">Merk Kendaraan</label>
        <div className="grid grid-cols-2 gap-2">
          {['TOYOTA', 'HONDA', 'BMW', 'AUDI', 'WULING', 'OTHERS'].map(b => (
            <button key={b} onClick={() => setVehicle({...vehicle, brand: b, model: '', brandOther: b === 'OTHERS' ? '' : undefined})} className={`p-4 glass-card rounded-2xl border-2 transition-all text-[0.6rem] font-black uppercase ${vehicle.brand === b ? 'border-primary-500 text-primary-500' : 'border-transparent dark:text-white text-gray-900'}`}>{b}</button>
          ))}
        </div>
        {vehicle.brand === 'OTHERS' && (
          <input placeholder="Ketik Merk Mobil" className="w-full p-4 glass-card rounded-xl outline-none font-bold dark:text-white border border-black/5" onChange={e => setVehicle({...vehicle, brandOther: e.target.value})} />
        )}
      </div>

      <div className="space-y-4">
        <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-widest ml-1">Tipe Kendaraan</label>
        <select 
          className="w-full p-4 glass-card rounded-xl outline-none font-bold dark:text-white border border-black/5"
          value={vehicle.model}
          onChange={e => {
            const m = CAR_DATABASE.find(c => c.modelName === e.target.value);
            const price = m?.yearPrices[vehicle.year] || 0;
            setVehicle({...vehicle, model: e.target.value, price: price * 1000000, basePriceFromList: price * 1000000});
          }}
        >
          <option value="">Pilih Tipe</option>
          {CAR_DATABASE.filter(c => c.brand === vehicle.brand).map(c => <option key={c.code} value={c.modelName}>{c.modelName}</option>)}
          <option value="OTHERS">Lainnya (Manual)</option>
        </select>
        {vehicle.model === 'OTHERS' && (
          <input placeholder="Ketik Tipe Mobil" className="w-full p-4 glass-card rounded-xl outline-none font-bold dark:text-white border border-black/5" onChange={e => setVehicle({...vehicle, modelOther: e.target.value})} />
        )}
      </div>

      <div className="space-y-2">
        <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-widest ml-1">Harga Kendaraan (Market Value)</label>
        <input 
          type="number" 
          value={vehicle.price} 
          onChange={e => setVehicle({...vehicle, price: Number(e.target.value)})}
          className="w-full p-4 glass-card rounded-xl outline-none font-black text-2xl text-primary-500 border border-black/5" 
        />
        {vehicle.basePriceFromList > 0 && (
          <p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest ml-1">Standard: {formatIDR(vehicle.basePriceFromList)} (+/- 10% allowed)</p>
        )}
      </div>

      <div className="space-y-2">
        <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-widest ml-1">Plat Nomor (AA-BBBB-CCC)</label>
        <input 
          placeholder="B 1234 ABC"
          value={vehicle.plate}
          onChange={e => {
            const val = e.target.value.toUpperCase();
            const prefix = val.split(' ')[0];
            setVehicle({...vehicle, plate: val, plateZone: getRegionFromPlate(prefix)});
          }}
          className="w-full p-5 glass-card rounded-2xl outline-none font-black text-xl tracking-widest dark:text-white border border-black/5 focus:border-primary-500" 
        />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="text-[0.5rem] font-black text-gray-500 uppercase mb-2 block">Penggunaan</label>
          <select className="w-full p-3 glass-card rounded-xl text-xs font-bold" value={vehicle.usage} onChange={e => setVehicle({...vehicle, usage: e.target.value as any})}>
            <option value="PERSONAL">Pribadi</option>
            <option value="COMMERCIAL">Komersial</option>
            <option value="OFFICIAL">Dinas</option>
          </select>
        </div>
        <div>
          <label className="text-[0.5rem] font-black text-gray-500 uppercase mb-2 block">Kondisi</label>
          <select className="w-full p-3 glass-card rounded-xl text-xs font-bold" value={vehicle.condition} onChange={e => setVehicle({...vehicle, condition: e.target.value as any})}>
            <option value="NEW">Baru</option>
            <option value="USED">Bekas</option>
          </select>
        </div>
      </div>

      <button 
        disabled={!vehicle.brand || !vehicle.model || !vehicle.plate || vehicle.price === 0}
        onClick={() => setStep(CarWizardStep.COVERAGE)} 
        className="w-full py-6 bg-primary-500 text-white rounded-[2rem] font-black uppercase text-sm shadow-xl shadow-primary-500/20 disabled:opacity-50"
      >
        Tentukan Perlindungan <ChevronRight size={18} className="inline ml-1"/>
      </button>
    </div>
  );

  const renderStep2 = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-2 gap-3">
        {[InsuranceType.COMPREHENSIVE, InsuranceType.TLO].map(t => (
          <button key={t} onClick={() => setVehicle({...vehicle, insuranceType: t})} className={`p-6 glass-card rounded-3xl border-2 transition-all flex flex-col items-center gap-2 ${vehicle.insuranceType === t ? 'border-primary-500 text-primary-500' : 'border-transparent dark:text-white text-gray-900'}`}>
            <Shield size={24}/>
            <span className="text-[0.6rem] font-black uppercase tracking-widest">{t}</span>
          </button>
        ))}
      </div>

      <div className="space-y-4">
        <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-widest ml-1">Perluasan OJK</label>
        <div className="grid grid-cols-1 gap-2">
          {[
            { id: 'flood', label: 'Banjir & Badai' },
            { id: 'earthquake', label: 'Gempa Bumi' },
            { id: 'srcc', label: 'SRCC (Hurura-hara)' },
            { id: 'terrorism', label: 'Terorisme' },
            { id: 'authorizedWorkshop', label: 'Bengkel Authorized (+0.2%)' }
          ].map(ex => (
            <button 
              key={ex.id}
              onClick={() => setVehicle({...vehicle, expansions: {...vehicle.expansions, [ex.id]: !((vehicle.expansions as any)[ex.id]) }})}
              className={`p-4 glass-card rounded-2xl border flex items-center justify-between transition-all ${ (vehicle.expansions as any)[ex.id] ? 'border-primary-500 bg-primary-500/5' : 'border-transparent'}`}
            >
              <span className="text-gray-900 dark:text-white text-[0.65rem] font-bold uppercase">{ex.label}</span>
              { (vehicle.expansions as any)[ex.id] && <CheckCircle2 size={16} className="text-primary-500"/>}
            </button>
          ))}
        </div>
      </div>

      <div className="p-4 glass-card rounded-2xl border border-black/5">
        <label className="text-[0.5rem] font-black text-gray-500 uppercase tracking-widest mb-2 block">Third Party Liability (TPL)</label>
        <select 
