             </button>
             <button onClick={() => setPage('claim')} className="p-8 glass-card rounded-[3rem] text-left border border-black/5 hover:border-primary-500/40 transition-all group">
                <div className="w-12 h-12 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500 mb-6 group-hover:scale-110 transition-transform"><Zap size={24}/></div>
                <p className="font-black text-xl leading-none dark:text-white uppercase tracking-tighter">Klaim</p>
                <p className="text-[0.6rem] text-gray-500 uppercase font-black tracking-widest mt-1">Neural Audit</p>
             </button>
          </div>

          <div className="p-10 glass-card rounded-[3.5rem] border border-black/5 space-y-4">
             <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-emerald-500/10 rounded-2xl flex items-center justify-center text-emerald-500"><CheckCircle2 size={28}/></div>
               <h3 className="font-black uppercase text-gray-900 dark:text-white tracking-tighter text-xl">Sistem Online</h3>
             </div>
             <p className="text-xs font-bold text-gray-500 uppercase tracking-widest leading-relaxed">Surepath Neural Link sedang berjalan optimal di wilayah Anda. Semua pengajuan akan diproses secara real-time.</p>
          </div>
        </div>
      )}

      {currentPage === 'car-flow' && <CarWizard onBack={() => setPage('home')} />}
      {currentPage === 'claim' && <ClaimScreen onBack={() => setPage('home')} />}

      {/* Mobile Navbar Placeholder */}
      <nav className="fixed bottom-6 inset-x-4 h-20 glass-card z-50 flex items-center justify-around px-2 rounded-[2rem] shadow-xl border border-black/5 max-w-lg mx-auto">
        {['home', 'products', 'claim', 'wallet', 'console'].map(id => (
           <button key={id} onClick={() => setPage(id === 'home' || id === 'claim' ? id : 'home')} className={`p-3 rounded-xl ${currentPage === id ? 'bg-primary-500/10 text-primary-500' : 'text-gray-400'}`}>
              {id === 'home' && <Home size={22}/>}
              {id === 'products' && <Grid size={22}/>}
              {id === 'claim' && <Zap size={22}/>}
              {id === 'wallet' && <Wallet size={22}/>}
              {id === 'console' && <Briefcase size={22}/>}
           </button>
        ))}
      </nav>
    </div>
  );
};

const ClaimScreen = ({ onBack }: { onBack: () => void }) => {
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        analyze(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const analyze = async (base64: string) => {
    setLoading(true);
    const res = await analyzeClaimPhoto(base64);
    setLoading(false);
    if (res.success && res.data) setResult(res.data);
  };

  return (
    <div className="p-6 max-w-lg mx-auto pb-32 animate-fade-in">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={onBack} className="p-2 dark:text-gray-400 text-gray-600"><ChevronLeft/></button>
        <h2 className="text-2xl font-black uppercase text-gray-900 dark:text-white">Neural <span className="text-primary-500">Claim</span></h2>
      </div>

      {!result ? (
        <div className="space-y-6">
          <div className="aspect-square glass-card rounded-[3rem] border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center p-12 text-center relative overflow-hidden">
            {loading ? (
              <div className="flex flex-col items-center gap-4">
                <Loader2 size={40} className="animate-spin text-primary-500" />
                <p className="text-[0.6rem] font-black uppercase tracking-[0.3em] text-primary-500">Analyzing Damage...</p>
              </div>
            ) : (
              <>
                <Camera size={48} className="text-primary-500 mb-4" />
                <p className="font-black dark:text-white text-gray-900 uppercase">Foto Kerusakan</p>
                <p className="text-[0.6rem] text-gray-500 mt-2 font-bold uppercase tracking-widest">AI akan menghitung estimasi biaya instan</p>
                <input type="file" accept="image/*" onChange={handleUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
              </>
            )}
          </div>
        </div>
      ) : (
        <div className="space-y-6 animate-fade-in">
          <div className="bg-primary-500 p-8 rounded-[3rem] text-white shadow-xl">
            <p className="text-[0.6rem] font-black uppercase tracking-widest opacity-80 mb-2">Estimasi Total</p>
            <h3 className="text-3xl font-black">{formatIDR(result.totalEstimasi)}</h3>
            <p className="mt-4 text-xs font-bold uppercase tracking-widest bg-white/20 inline-block px-3 py-1 rounded-lg">Severity: {result.severity}</p>
          </div>
          <div className="space-y-3">
            {result.rincianPart.map((p, i) => (
              <div key={i} className="p-4 glass-card rounded-2xl flex justify-between items-center">
                <div>
                  <p className="text-xs font-black dark:text-white text-gray-900 uppercase">{p.namaPart}</p>
                  <p className="text-[0.6rem] text-gray-500 uppercase font-bold">{p.kondisi} • {p.tindakan}</p>
                </div>
                <p className="text-sm font-black text-primary-500">{formatIDR(p.estimasiBiaya)}</p>
              </div>
            ))}
          </div>
          <button onClick={() => setResult(null)} className="w-full py-5 glass-card rounded-2xl font-black uppercase text-[0.7rem] tracking-widest dark:text-white text-gray-900">Analisa Baru</button>
        </div>
      )}
    </div>
  );
};

export default App;
